"""Proposal synthesis — generate full-length research proposals via free-text LLM generation."""

import logging
import re
from pathlib import Path

from jinja2 import Template

from backend.pipeline.feasibility.feasibility_scorer import FeasibilityReport
from backend.pipeline.generation.models import ResearchIdea
from backend.pipeline.literature.models import Paper
from backend.pipeline.novelty.novelty_checker import NoveltyReport
from backend.providers.base import LLMProvider

logger = logging.getLogger(__name__)

PROMPT_DIR = Path(__file__).parent / "prompts"

# Section markers the LLM must produce — used for parsing free-text output
REQUIRED_SECTIONS = [
    "Title",
    "Abstract",
    "Introduction",
    "Related Work",
    "Proposed Method",
    "Expected Contributions",
    "Evaluation Plan",
    "Timeline",
    "References",
    "Risk Mitigation",
]

# Minimum word counts per section — enforced on generation
MIN_WORDS = {
    "abstract": 150,
    "introduction": 400,
    "related_work": 300,
    "proposed_method": 500,
    "expected_contributions": 150,
    "evaluation_plan": 300,
    "timeline": 100,
    "risk_mitigation": 150,
}


class ResearchProposal:
    def __init__(self, idea_id: int | None = None, **sections):
        self.idea_id = idea_id
        self.sections = sections

    @property
    def title(self) -> str:
        return self.sections.get("title", "Untitled Proposal")

    @property
    def abstract(self) -> str:
        return self.sections.get("abstract", "")

    def to_markdown(self) -> str:
        """Convert proposal to Markdown format."""
        md_parts = []
        for key, value in self.sections.items():
            if key == "references":
                md_parts.append("## References\n")
                if isinstance(value, list):
                    for i, ref in enumerate(value, 1):
                        if isinstance(ref, dict):
                            authors = ref.get("authors", "Unknown")
                            year = ref.get("year", "n.d.")
                            title = ref.get("title", "Untitled")
                            venue = ref.get("venue", "")
                            doi = ref.get("doi", "")
                            url = ref.get("url", "")
                            line = f"[{i}] {authors} ({year}). {title}."
                            if venue:
                                line += f" {venue}."
                            if doi:
                                line += f" DOI: {doi}"
                            elif url:
                                line += f" URL: {url}"
                            md_parts.append(line)
                        else:
                            md_parts.append(f"- {ref}")
                elif isinstance(value, str):
                    # Free-text references — emit as-is
                    md_parts.append(value)
            elif key == "evaluation_plan" and isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    if isinstance(sub_val, list):
                        md_parts.append(f"**{sub_header}**: " + ", ".join(str(v) for v in sub_val))
                    else:
                        md_parts.append(f"**{sub_header}**: {sub_val}")
            elif isinstance(value, str):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n\n{value}")
            elif isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    md_parts.append(f"**{sub_header}**: {sub_val}")
        return "\n\n".join(md_parts)

    def word_count(self) -> int:
        """Total word count across all sections."""
        total = 0
        for v in self.sections.values():
            if isinstance(v, str):
                total += len(v.split())
            elif isinstance(v, list):
                for item in v:
                    if isinstance(item, str):
                        total += len(item.split())
                    elif isinstance(item, dict):
                        total += sum(len(str(x).split()) for x in item.values())
            elif isinstance(v, dict):
                total += sum(len(str(x).split()) for x in v.values())
        return total


class ProposalSynthesizer:
    def __init__(self, provider: LLMProvider, ensemble_reviewer=None):
        self._provider = provider
        self._ensemble_reviewer = ensemble_reviewer
        self._prompt_template = (PROMPT_DIR / "synthesis_system.md").read_text()

    async def synthesize(
        self,
        idea: ResearchIdea,
        novelty_report: NoveltyReport | None = None,
        feasibility_report: FeasibilityReport | None = None,
        supporting_papers: list[Paper] | None = None,
        gaps: list | None = None,
    ) -> ResearchProposal:
        """Generate a full-length research proposal via free-text LLM generation."""
        literature = self._format_literature(supporting_papers or [])
        key_risks = feasibility_report.key_risks if feasibility_report else []

        gap_descriptions = ""
        if gaps:
            gap_lines = []
            for g in gaps[:8]:
                gap_lines.append(
                    f"- **{g.title}** (confidence: {g.confidence:.2f}, type: {g.gap_type}): "
                    f"{g.description}"
                )
            gap_descriptions = "\n".join(gap_lines)

        closest_matches = ""
        if novelty_report and novelty_report.closest_matches:
            match_lines = []
            for m in novelty_report.closest_matches[:5]:
                title = m.get("title", "Unknown")
                dist = m.get("distance", "N/A")
                abstract = m.get("abstract", "")
                line = f"- **{title}** (distance: {dist})"
                if abstract:
                    line += f"\n  Abstract: {abstract}"
                match_lines.append(line)
            closest_matches = "\n".join(match_lines)

        feasibility_reasoning = ""
        if feasibility_report:
            feasibility_reasoning = (
                f"Overall feasibility: {feasibility_report.overall_score:.1f}/10\n"
                f"Reasoning: {feasibility_report.reasoning}\n"
                f"Sub-scores: data={feasibility_report.data_availability:.1f}, "
                f"compute={feasibility_report.computational_requirements:.1f}, "
                f"methods={feasibility_report.methodological_complexity:.1f}, "
                f"eval={feasibility_report.evaluation_plan:.1f}, "
                f"novelty_grounding={feasibility_report.novelty_grounding:.1f}, "
                f"impact={feasibility_report.impact_potential:.1f}"
            )

        prompt = Template(self._prompt_template).render(
            title=idea.title,
            problem=idea.problem_statement,
            method=idea.proposed_method,
            contributions=idea.expected_contributions,
            evaluation=idea.evaluation_approach,
            novelty_arguments=novelty_report.novelty_arguments
            if novelty_report
            else "Not assessed",
            timeline=feasibility_report.estimated_timeline if feasibility_report else "3-6 months",
            risks="; ".join(key_risks) if key_risks else "Not assessed",
            key_risks=key_risks,
            literature=literature,
            gap_descriptions=gap_descriptions,
            closest_matches=closest_matches,
            feasibility_reasoning=feasibility_reasoning,
        )

        try:
            # ── Pass 1: Free-text generation ──────────────────────────
            raw_text = await self._provider.complete(
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "You are a senior researcher writing a full research proposal for a "
                            "competitive conference (ACL, EMNLP, NeurIPS, or similar). You MUST "
                            "produce ALL sections with substantial content. Do NOT write stubs, "
                            "summaries, or placeholder text. Each section must be detailed and "
                            "technically precise.\n\n"
                            "OUTPUT FORMAT: Write each section with a markdown header like:\n"
                            "## Title\n...\n## Abstract\n...\n## Introduction\n...\n"
                            "## Related Work\n...\n## Proposed Method\n...\n"
                            "## Expected Contributions\n...\n## Evaluation Plan\n...\n"
                            "## Timeline\n...\n## References\n...\n## Risk Mitigation\n...\n\n"
                            "You MUST include ALL 10 sections. Each prose section must be at least "
                            "200 words. The Proposed Method must be at least 500 words with "
                            "mathematical notation ($...$). The Introduction must be at least 400 words."
                        ),
                    },
                    {"role": "user", "content": prompt},
                ],
                temperature=0.4,
                max_tokens=8192,
            )

            proposal = self._parse_sections(raw_text, idea_id=None)

            # ── Quality check: expand short sections ──────────────────
            short_sections = self._find_short_sections(proposal)
            if short_sections:
                logger.info(
                    "Expanding %d short sections: %s",
                    len(short_sections),
                    ", ".join(short_sections),
                )
                proposal = await self._expand_sections(
                    proposal, short_sections, idea
                )

            # ── Ensemble review ───────────────────────────────────────
            if self._ensemble_reviewer:
                try:
                    review_result = await self._ensemble_reviewer.review(proposal, idea)
                    proposal.sections["ensemble_review"] = review_result
                except Exception as e:
                    logger.warning("Ensemble review failed: %s", e)

            return proposal

        except Exception as e:
            logger.error("Proposal synthesis failed: %s", e)
            return ResearchProposal(
                title=idea.title,
                abstract=idea.problem_statement,
                introduction="Synthesis failed due to an error. Please retry.",
                proposed_method=idea.proposed_method,
            )

    @staticmethod
    def _parse_sections(raw_text: str, idea_id: int | None = None) -> ResearchProposal:
        """Parse free-text markdown output into a ResearchProposal with keyed sections."""
        sections: dict[str, str | list] = {}

        # Split on ## headers
        pattern = r"##\s+(" + "|".join(REQUIRED_SECTIONS) + r")\s*\n"
        parts = re.split(pattern, raw_text)

        # parts alternates: [preamble, section_name, content, section_name, content, ...]
        i = 1
        while i < len(parts) - 1:
            section_name = parts[i].strip()
            content = parts[i + 1].strip()
            key = section_name.lower().replace(" ", "_")

            # Try to parse references as list
            if key == "references":
                sections[key] = ProposalSynthesizer._parse_references(content)
            else:
                sections[key] = content

            i += 2

        # If there's preamble text before first ## header, check for title
        if parts[0].strip() and "title" not in sections:
            first_line = parts[0].strip().split("\n")[0]
            if first_line and not first_line.startswith("#"):
                sections["title"] = first_line

        return ResearchProposal(idea_id=idea_id, **sections)

    @staticmethod
    def _parse_references(text: str) -> str | list[dict]:
        """Try to parse references into structured dicts; fall back to raw text."""
        refs = []
        # Match patterns like [1] Author (Year). Title. Venue.
        for m in re.finditer(
            r"\[\d+\]\s*(.+?)(?:\n|$)",
            text,
        ):
            line = m.group(1).strip()
            refs.append({"raw": line})

        if refs:
            return refs
        return text  # Return raw text if parsing fails

    @staticmethod
    def _find_short_sections(proposal: ResearchProposal) -> list[str]:
        """Return list of section keys that don't meet minimum word counts."""
        short = []
        for key, minimum in MIN_WORDS.items():
            content = proposal.sections.get(key, "")
            if isinstance(content, str) and len(content.split()) < minimum:
                short.append(key)
        return short

    async def _expand_sections(
        self,
        proposal: ResearchProposal,
        short_sections: list[str],
        idea: ResearchIdea,
    ) -> ResearchProposal:
        """Expand sections that are too short via a follow-up LLM call."""
        expand_prompt = (
            f"The following research proposal has sections that are too short. "
            f"Expand ONLY these sections: {', '.join(short_sections)}.\n\n"
            f"Research idea: {idea.title}\n"
            f"Problem: {idea.problem_statement}\n"
            f"Method: {idea.proposed_method}\n\n"
        )
        for key in short_sections:
            current = proposal.sections.get(key, "")
            if isinstance(current, str):
                expand_prompt += f"## {key.replace('_', ' ').title()}\n{current}\n\n"

        expand_prompt += (
            "\nRewrite ONLY the sections above. Each must be detailed and technically precise. "
            "Use markdown ## headers. The Introduction must be 400+ words. "
            "The Proposed Method must be 500+ words with math notation. "
            "Related Work must be 300+ words citing specific papers."
        )

        try:
            expansion = await self._provider.complete(
                messages=[
                    {
                        "role": "system",
                        "content": "You are a senior researcher expanding thin sections of a research proposal. Produce full-length, publication-quality prose.",
                    },
                    {"role": "user", "content": expand_prompt},
                ],
                temperature=0.4,
                max_tokens=6144,
            )

            expanded = self._parse_sections(expansion, idea_id=proposal.idea_id)
            # Merge expanded sections back in
            for key in short_sections:
                if key in expanded.sections:
                    new_content = expanded.sections[key]
                    if isinstance(new_content, str) and len(new_content.split()) > len(
                        str(proposal.sections.get(key, "")).split()
                    ):
                        proposal.sections[key] = new_content

        except Exception as e:
            logger.warning("Section expansion failed: %s", e)

        return proposal

    @staticmethod
    def _format_literature(papers: list[Paper]) -> str:
        if not papers:
            return "No specific supporting papers provided."
        lines = []
        for p in papers[:15]:
            authors = ", ".join(a.name for a in p.authors[:3])
            if len(p.authors) > 3:
                authors += " et al."
            line = f"- {authors} ({p.year or 'n.d.'}). {p.title}. {p.venue or 'Unknown venue'}."
            if p.doi:
                line += f" DOI: {p.doi}."
            elif p.url:
                line += f" URL: {p.url}."
            if p.arxiv_id:
                line += f" arXiv: {p.arxiv_id}."
            if p.abstract:
                line += f"\n  Abstract: {p.abstract[:200]}"
            lines.append(line)
        return "\n".join(lines)

"""Entity-centric knowledge graph with Hebbian-like edge consolidation.

Stores entities (papers, authors, methods, datasets, concepts) and their
relationships (cites, uses_method, extends, contradicts, etc.) in an
in-memory graph with JSON persistence. Optional changeset versioning
and adjacency indexing for O(1) neighbor lookup.
"""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import TYPE_CHECKING

from backend.pipeline.knowledge.entities import EntityResolution, EntityType, KnowledgeEntity
from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
from backend.pipeline.knowledge.truth import TruthValue

if TYPE_CHECKING:
    from backend.pipeline.knowledge.activation import ActivationPipeline
    from backend.pipeline.knowledge.adjacency import AdjacencyIndex
    from backend.pipeline.knowledge.streams import StreamRegistry
    from backend.pipeline.knowledge.versioning import ChangeBuffer, VersionLog

logger = logging.getLogger(__name__)


class KnowledgeGraph:
    """Entity-centric knowledge graph with Hebbian-like edge consolidation."""

    def __init__(
        self, persist_path: str = "./data/knowledge_graph.json", versioning_enabled: bool = False
    ):
        self._path = Path(persist_path)
        self._entities: dict[str, KnowledgeEntity] = {}
        self._relationships: list[KnowledgeRelationship] = []
        self._resolution = EntityResolution()
        self._hash_index: dict[str, str] = {}
        self._incoming_set: dict[str, set[str]] = {}
        self._versioning_enabled = versioning_enabled
        self._change_buffer: ChangeBuffer | None = None
        self._version_log: VersionLog | None = None
        self._adjacency: AdjacencyIndex | None = None
        self._stream_registry: StreamRegistry | None = None
        if versioning_enabled:
            from backend.pipeline.knowledge.adjacency import AdjacencyIndex
            from backend.pipeline.knowledge.versioning import ChangeBuffer, VersionLog

            changes_path = str(persist_path).replace(".json", ".changes.jsonl")
            self._change_buffer = ChangeBuffer()
            self._version_log = VersionLog(changes_path)
            self._adjacency = AdjacencyIndex()
        self._load()

    def add_entity(self, entity: KnowledgeEntity) -> str:
        """Add an entity. Returns canonical ID. Deduplicates by content hash when IDs match."""
        canonical = self._resolution.canonical_id(entity.id)
        content_hash = entity.content_hash

        if canonical in self._entities:
            existing = self._entities[canonical]
            if self._change_buffer:
                from backend.pipeline.knowledge.versioning import ChangeRecord

                old_hash = ChangeRecord.compute_content_hash(existing.model_dump(mode="json"))
            existing.truth = existing.truth.revise(entity.truth)
            if self._change_buffer:
                new_hash = ChangeRecord.compute_content_hash(existing.model_dump(mode="json"))
                self._change_buffer.record_truth_update(canonical, old_hash, new_hash)
            self._hash_index[content_hash] = canonical
            return canonical

        # Content-hash dedup: same content, same ID path — revise truth
        if content_hash in self._hash_index:
            existing_id = self._hash_index[content_hash]
            if existing_id == canonical:
                existing = self._entities.get(existing_id)  # type: ignore[assignment]
                if existing:
                    if self._change_buffer:
                        from backend.pipeline.knowledge.versioning import ChangeRecord

                        old_hash = ChangeRecord.compute_content_hash(
                            existing.model_dump(mode="json")
                        )
                    existing.truth = existing.truth.revise(entity.truth)
                    if self._change_buffer:
                        new_hash = ChangeRecord.compute_content_hash(
                            existing.model_dump(mode="json")
                        )
                        self._change_buffer.record_truth_update(existing_id, old_hash, new_hash)
                    return existing_id

        self._entities[canonical] = entity
        self._hash_index[content_hash] = canonical
        if self._change_buffer:
            from backend.pipeline.knowledge.versioning import ChangeRecord

            ch = ChangeRecord.compute_content_hash(entity.model_dump(mode="json"))
            self._change_buffer.record_entity_add(canonical, ch)
        return canonical

    def add_relationship(self, rel: KnowledgeRelationship) -> None:
        """Add a relationship. If similar one exists, reinforce weight."""
        source = self._resolution.canonical_id(rel.source_id)
        target = self._resolution.canonical_id(rel.target_id)

        for existing in self._relationships:
            if (
                self._resolution.canonical_id(existing.source_id) == source
                and self._resolution.canonical_id(existing.target_id) == target
                and existing.relation_type == rel.relation_type
            ):
                self.reinforce(source, target, rel.relation_type, delta=0.1)
                existing.truth = existing.truth.revise(rel.truth)
                return

        self._relationships.append(
            KnowledgeRelationship(
                source_id=source,
                target_id=target,
                relation_type=rel.relation_type,
                weight=rel.weight,
                evidence=rel.evidence,
                truth=rel.truth,
            )
        )
        self._incoming_set.setdefault(target, set()).add(source)
        if self._adjacency:
            self._adjacency.add_relationship(source, target)
        if self._change_buffer:
            from backend.pipeline.knowledge.versioning import ChangeRecord

            content_hash = ChangeRecord.compute_content_hash(rel.model_dump(mode="json"))
            self._change_buffer.record_relationship_add(source, target, content_hash)

        # Truth-value revision when CONTRADICTS relation is added
        if rel.relation_type == RelationType.CONTRADICTS:
            src_entity = self._entities.get(source)
            tgt_entity = self._entities.get(target)
            for entity in (src_entity, tgt_entity):
                if entity and hasattr(entity, 'truth') and entity.truth:
                    entity.truth = TruthValue(
                        frequency=entity.truth.frequency,
                        confidence=entity.truth.confidence * 0.8,
                        evidence_count=entity.truth.evidence_count,
                    )

    def get_entity(self, entity_id: str) -> KnowledgeEntity | None:
        """Get an entity by ID (resolves to canonical)."""
        canonical = self._resolution.canonical_id(entity_id)
        return self._entities.get(canonical)

    def get_by_content_hash(self, content_hash: str) -> KnowledgeEntity | None:
        """Get an entity by its content hash (O(1) reverse lookup)."""
        entity_id = self._hash_index.get(content_hash)
        if entity_id:
            return self._entities.get(entity_id)
        return None

    def get_referencing_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        """Get all relationships that reference this entity (incoming + outgoing)."""
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r
            for r in self._relationships
            if self._resolution.canonical_id(r.source_id) == canonical
            or self._resolution.canonical_id(r.target_id) == canonical
        ]

    def get_outgoing_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r for r in self._relationships
            if self._resolution.canonical_id(r.source_id) == canonical
        ]

    def get_incoming_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r for r in self._relationships
            if self._resolution.canonical_id(r.target_id) == canonical
        ]

    @property
    def entity_count(self) -> int:
        return len(self._entities)

    def get_neighbors(
        self,
        entity_id: str,
        relation_type: RelationType | None = None,
    ) -> list[KnowledgeEntity]:
        """Get neighboring entities connected by relationships."""
        canonical = self._resolution.canonical_id(entity_id)

        if self._adjacency and relation_type is None:
            neighbor_ids = self._adjacency.get_neighbor_ids(canonical)
            return [self._entities[nid] for nid in neighbor_ids if nid in self._entities]

        # Linear scan fallback (used when filtering by relation_type or no adjacency index)
        found_neighbors: set[str] = set()
        for rel in self._relationships:
            src = self._resolution.canonical_id(rel.source_id)
            tgt = self._resolution.canonical_id(rel.target_id)
            if relation_type and rel.relation_type != relation_type:
                continue
            if src == canonical:
                found_neighbors.add(tgt)
            elif tgt == canonical:
                found_neighbors.add(src)

        return [self._entities[nid] for nid in found_neighbors if nid in self._entities]

    def reinforce(
        self,
        source_id: str,
        target_id: str,
        relation_type: RelationType,
        delta: float = 0.1,
    ) -> None:
        """Increase edge weight (Hebbian-like reinforcement)."""
        source = self._resolution.canonical_id(source_id)
        target = self._resolution.canonical_id(target_id)

        for rel in self._relationships:
            if (
                self._resolution.canonical_id(rel.source_id) == source
                and self._resolution.canonical_id(rel.target_id) == target
                and rel.relation_type == relation_type
            ):
                old_weight = rel.weight
                rel.weight = min(2.0, rel.weight + delta)
                if self._change_buffer:
                    self._change_buffer.record_reinforce(source, target, old_weight, rel.weight)
                return

    def weaken(
        self,
        source_id: str,
        target_id: str,
        relation_type: RelationType,
        delta: float = 0.05,
    ) -> None:
        """Decrease edge weight (Hebbian-like weakening)."""
        source = self._resolution.canonical_id(source_id)
        target = self._resolution.canonical_id(target_id)

        for rel in self._relationships:
            if (
                self._resolution.canonical_id(rel.source_id) == source
                and self._resolution.canonical_id(rel.target_id) == target
                and rel.relation_type == relation_type
            ):
                old_weight = rel.weight
                rel.weight = max(0.0, rel.weight - delta)
                if self._change_buffer:
                    self._change_buffer.record_weaken(source, target, old_weight, rel.weight)
                return

    def merge_entities(self, id_a: str, id_b: str) -> None:
        """Merge two entities (e.g., duplicate author names)."""
        self._resolution.union(id_a, id_b)
        canonical = self._resolution.canonical_id(id_a)
        other = id_b if canonical == id_a else id_a

        if other in self._entities and canonical not in self._entities:
            entity = self._entities.pop(other)
            entity.id = canonical
            self._entities[canonical] = entity

        if self._change_buffer:
            self._change_buffer.record_merge(canonical, other)
        if self._adjacency:
            self._adjacency.remove_entity(other)

    def get_graph_stats(self) -> dict:
        """Return graph statistics."""
        return {
            "entity_count": len(self._entities),
            "relationship_count": len(self._relationships),
            "entity_types": {
                et.value: sum(1 for e in self._entities.values() if e.entity_type == et)
                for et in EntityType
            },
            "relation_types": {
                rt.value: sum(1 for r in self._relationships if r.relation_type == rt)
                for rt in RelationType
            },
        }

    def _load(self) -> None:
        if not self._path.exists():
            return
        try:
            data = json.loads(self._path.read_text())
            for ed in data.get("entities", []):
                entity = KnowledgeEntity(**ed)
                self._entities[entity.id] = entity
                self._hash_index[entity.content_hash] = entity.id
                self._resolution.find(entity.id)
            for rd in data.get("relationships", []):
                self._relationships.append(KnowledgeRelationship(**rd))
            if self._adjacency:
                edges = [(r.source_id, r.target_id) for r in self._relationships]
                self._adjacency.rebuild(edges)
            logger.info(
                "Loaded knowledge graph: %d entities, %d relationships",
                len(self._entities),
                len(self._relationships),
            )
        except Exception as e:
            logger.warning("Failed to load knowledge graph: %s", e)

    def save(self) -> None:
        """Persist the knowledge graph to disk."""
        self._path.parent.mkdir(parents=True, exist_ok=True)
        if self._change_buffer and self._version_log:
            records = self._change_buffer.flush()
            self._version_log.append(records)
            if self._stream_registry:
                self._stream_registry.process_changes(records)
        data = {
            "entities": [e.model_dump(mode="json") for e in self._entities.values()],
            "relationships": [r.model_dump(mode="json") for r in self._relationships],
        }
        self._path.write_text(json.dumps(data, indent=2, default=str))

    def get_version_log(self) -> VersionLog | None:
        return self._version_log

    def get_changes_since(self, version: int):
        if self._version_log:
            return self._version_log.get_changes_since(version)
        return []

    def attach_stream_registry(self, registry: StreamRegistry) -> None:
        self._stream_registry = registry

    def compute_activation(self, entity_id: str, pipeline: ActivationPipeline) -> float:
        entity = self.get_entity(entity_id)
        if not entity:
            return 0.0
        from backend.pipeline.knowledge.activation import ActivationContext

        context = ActivationContext(
            entity_id=entity_id,
            current_truth=entity.truth,
        )
        return pipeline.compute(context)

    def rank_entities_by_activation(
        self, entity_type: EntityType | None, pipeline: ActivationPipeline
    ) -> list[tuple[str, float]]:
        results = []
        for eid, entity in self._entities.items():
            if entity_type and entity.entity_type != entity_type:
                continue
            score = self.compute_activation(eid, pipeline)
            results.append((eid, score))
        return sorted(results, key=lambda x: x[1], reverse=True)

"""Epistemic truth maintenance via OpenNARS-inspired truth calculus.

Each knowledge assertion (gap, idea, relationship) carries a TruthValue
with frequency (proportion of supporting evidence) and confidence
(total evidence relative to evidential horizon). New evidence revises
existing truth via weighted averaging rather than overwriting.
"""

from pydantic import BaseModel


class TruthValue(BaseModel):
    """OpenNARS-inspired evidential truth value.

    frequency = P(proposition is true | evidence)
    confidence = P(evidence is sufficient)
    """

    frequency: float = 0.5
    confidence: float = 0.5
    evidence_count: int = 0
    propagation_debt: float = 0.0  # How stale downstream consumers are

    @property
    def expectation(self) -> float:
        """Weighted expectation: frequency * confidence."""
        return self.frequency * self.confidence

    def revise(self, other: "TruthValue") -> "TruthValue":
        """Weighted revision when new evidence arrives.

        Uses the OpenNARS revision rule: weights are derived from
        confidence values, and the new truth is a weighted average.
        """
        w1 = self.confidence / (1 - self.confidence + 1e-10)
        w2 = other.confidence / (1 - other.confidence + 1e-10)
        total_w = w1 + w2
        if total_w == 0:
            return TruthValue(
                frequency=0.5,
                confidence=0.5,
                evidence_count=self.evidence_count + other.evidence_count,
            )
        new_freq = (w1 * self.frequency + w2 * other.frequency) / total_w
        new_conf = total_w / (total_w + 1)
        # Propagation debt: how much truth changed, flagging downstream consumers as stale
        debt = abs(new_freq - self.frequency) * self.confidence
        return TruthValue(
            frequency=max(0.0, min(1.0, new_freq)),
            confidence=min(0.99, new_conf),
            evidence_count=self.evidence_count + other.evidence_count + 1,
            propagation_debt=debt,
        )

    def decay(self, rate: float = 0.99) -> "TruthValue":
        """Temporal truth decay. Confidence decreases over time."""
        return TruthValue(
            frequency=self.frequency,
            confidence=self.confidence * rate,
            evidence_count=self.evidence_count,
        )

    def settle_debt(self) -> "TruthValue":
        """Mark propagation debt as resolved after downstream update."""
        return TruthValue(
            frequency=self.frequency,
            confidence=self.confidence,
            evidence_count=self.evidence_count,
            propagation_debt=0.0,
        )

    @staticmethod
    def from_observation(frequency: float = 1.0) -> "TruthValue":
        """Create a TruthValue from a single observation."""
        return TruthValue(
            frequency=frequency,
            confidence=0.5,
            evidence_count=1,
        )

    @staticmethod
    def initial() -> "TruthValue":
        """Default truth value for new assertions with no prior evidence."""
        return TruthValue(
            frequency=0.5,
            confidence=0.5,
            evidence_count=0,
        )

"""Embedding provider abstraction — pluggable embedding backends.

Separates embedding generation from LLM completion, allowing different
models and providers for each task.

Reference: mem0 EmbedderFactory (11 providers), letta EmbeddingConfig (16 endpoint types).
"""

from __future__ import annotations

import asyncio
import hashlib
import logging
from abc import ABC, abstractmethod

logger = logging.getLogger(__name__)


class EmbeddingProvider(ABC):
    """Abstract embedding provider."""

    @abstractmethod
    async def embed(self, texts: list[str]) -> list[list[float]]:
        """Generate embeddings for a list of texts."""
        ...

    @property
    @abstractmethod
    def dimension(self) -> int:
        """Return the embedding dimension for this provider."""
        ...

    @property
    @abstractmethod
    def provider_name(self) -> str:
        """Return the provider name for logging."""
        ...


class OpenAIEmbeddingProvider(EmbeddingProvider):
    """OpenAI embeddings via the openai SDK."""

    def __init__(
        self,
        model: str = "text-embedding-3-small",
        api_key: str | None = None,
        dimension_override: int | None = None,
    ):
        import openai

        self._client = openai.AsyncOpenAI(api_key=api_key) if api_key else openai.AsyncOpenAI()
        self._model = model
        self._dimension = dimension_override or self._default_dimension(model)

    @staticmethod
    def _default_dimension(model: str) -> int:
        dims = {
            "text-embedding-3-small": 1536,
            "text-embedding-3-large": 3072,
            "text-embedding-ada-002": 1536,
        }
        return dims.get(model, 1536)

    async def embed(self, texts: list[str]) -> list[list[float]]:
        response = await self._client.embeddings.create(model=self._model, input=texts)
        return [item.embedding for item in response.data]

    @property
    def dimension(self) -> int:
        return self._dimension

    @property
    def provider_name(self) -> str:
        return f"openai:{self._model}"


class GeminiEmbeddingProvider(EmbeddingProvider):
    """Google Gemini embeddings via the generativeai SDK."""

    def __init__(
        self,
        model: str = "models/embedding-001",
        api_key: str | None = None,
    ):
        import google.generativeai as genai

        if api_key:
            genai.configure(api_key=api_key)
        self._model = model
        self._genai = genai

    async def embed(self, texts: list[str]) -> list[list[float]]:
        result = await asyncio.to_thread(
            self._genai.embed_content,
            model=self._model,
            content=texts,
            task_type="retrieval_document",
        )
        return result["embedding"]

    @property
    def dimension(self) -> int:
        dims = {
            "models/embedding-001": 768,
            "models/text-embedding-004": 768,
        }
        return dims.get(self._model, 768)

    @property
    def provider_name(self) -> str:
        return f"gemini:{self._model}"


class OllamaEmbeddingProvider(EmbeddingProvider):
    """Ollama embeddings via local HTTP API."""

    def __init__(
        self,
        model: str = "nomic-embed-text",
        base_url: str = "http://localhost:11434",
    ):
        import httpx

        self._client = httpx.AsyncClient(timeout=60.0)
        self._model = model
        self._base_url = base_url
        self._dim: int | None = None

    async def embed(self, texts: list[str]) -> list[list[float]]:
        embeddings = []
        for text in texts:
            response = await self._client.post(
                f"{self._base_url}/api/embeddings",
                json={"model": self._model, "prompt": text},
            )
            response.raise_for_status()
            emb = response.json()["embedding"]
            embeddings.append(emb)
            if self._dim is None:
                self._dim = len(emb)
        return embeddings

    @property
    def dimension(self) -> int:
        return self._dim or 768

    @property
    def provider_name(self) -> str:
        return f"ollama:{self._model}"


class FallbackEmbeddingProvider(EmbeddingProvider):
    """Provider that tries primary, then falls back to secondary on failure."""

    def __init__(self, primary: EmbeddingProvider, fallback: EmbeddingProvider):
        self._primary = primary
        self._fallback = fallback

    async def embed(self, texts: list[str]) -> list[list[float]]:
        try:
            return await self._primary.embed(texts)
        except Exception as e:
            logger.warning(
                "Primary embedding provider %s failed: %s, using fallback",
                self._primary.provider_name,
                e,
            )
            return await self._fallback.embed(texts)

    @property
    def dimension(self) -> int:
        return self._primary.dimension

    @property
    def provider_name(self) -> str:
        return f"fallback({self._primary.provider_name}+{self._fallback.provider_name})"


class DummyEmbeddingProvider(EmbeddingProvider):
    """No-op embedding provider for testing / environments without API access.

    Returns deterministic zero vectors of the configured dimension.
    Useful when the LLM provider (e.g. z.ai) does not offer an embedding endpoint.
    """

    def __init__(self, dimension: int = 1536):
        self._dimension = dimension

    async def embed(self, texts: list[str]) -> list[list[float]]:
        return [[0.0] * self._dimension for _ in texts]

    @property
    def dimension(self) -> int:
        return self._dimension

    @property
    def provider_name(self) -> str:
        return f"dummy:{self._dimension}d"


class CachedEmbeddingProvider(EmbeddingProvider):
    """Caching wrapper — stores text_hash → embedding in memory.

    Avoids re-embedding identical text across pipeline stages.
    """

    def __init__(self, wrapped: EmbeddingProvider, max_size: int = 10000):
        self._wrapped = wrapped
        self._cache: dict[str, list[float]] = {}
        self._max_size = max_size
        self._hits = 0
        self._misses = 0

    async def embed(self, texts: list[str]) -> list[list[float]]:
        results: list[list[float] | None] = [None] * len(texts)
        uncached_indices: list[int] = []
        uncached_texts: list[str] = []

        for i, text in enumerate(texts):
            key = hashlib.sha256(text.encode()).hexdigest()
            if key in self._cache:
                results[i] = self._cache[key]
                self._hits += 1
            else:
                uncached_indices.append(i)
                uncached_texts.append(text)
                self._misses += 1

        if uncached_texts:
            embeddings = await self._wrapped.embed(uncached_texts)
            for idx, emb in zip(uncached_indices, embeddings):
                results[idx] = emb
                key = hashlib.sha256(texts[idx].encode()).hexdigest()
                if len(self._cache) < self._max_size:
                    self._cache[key] = emb

        total = self._hits + self._misses
        if total > 0 and total % 100 == 0:
            logger.info(
                "Embedding cache: %d hits / %d total (%.1f%%)",
                self._hits, total, 100 * self._hits / total,
            )

        return results  # type: ignore[return-value]

    @property
    def dimension(self) -> int:
        return self._wrapped.dimension

    @property
    def provider_name(self) -> str:
        return f"cached({self._wrapped.provider_name})"


def create_embedding_provider(
    provider_name: str,
    model: str | None = None,
    api_key: str | None = None,
    base_url: str | None = None,
    dimension: int | None = None,
) -> EmbeddingProvider:
    """Factory: create an EmbeddingProvider by name.

    Args:
        provider_name: "openai", "gemini", "ollama"
        model: Model name (provider-specific default if omitted)
        api_key: API key for cloud providers
        base_url: Base URL for Ollama
        dimension: Override embedding dimension
    """
    name = provider_name.lower().strip()

    if name in ("dummy", "noop", "test"):
        return DummyEmbeddingProvider(dimension=dimension or 1536)
    elif name == "openai":
        provider = OpenAIEmbeddingProvider(
            model=model or "text-embedding-3-small",
            api_key=api_key,
            dimension_override=dimension,
        )
    elif name in ("gemini", "google"):
        provider = GeminiEmbeddingProvider(
            model=model or "models/embedding-001",
            api_key=api_key,
        )
    elif name == "ollama":
        return OllamaEmbeddingProvider(
            model=model or "nomic-embed-text",
            base_url=base_url or "http://localhost:11434",
        )
    else:
        raise ValueError(f"Unknown embedding provider: {provider_name}")

    # Wrap cloud providers with cache (local Ollama doesn't benefit)
    return CachedEmbeddingProvider(provider)

"""Unified literature search across multiple academic APIs."""

import asyncio
import hashlib
import logging

from backend.config import get_settings
from backend.pipeline.literature.base import AcademicSearchSource
from backend.pipeline.literature.models import Paper, SearchResult

logger = logging.getLogger(__name__)


class SearchService:
    """Search across multiple academic sources with deduplication."""

    def __init__(self, sources: list[AcademicSearchSource] | None = None):
        if sources is None:
            sources = self._default_sources()
        self._sources: dict[str, AcademicSearchSource] = {s.source_name: s for s in sources}

    async def search_all(
        self,
        query: str,
        sources: list[str] | None = None,
        limit_per_source: int = 20,
        year_from: int | None = None,
        year_to: int | None = None,
        deduplicate: bool = True,
    ) -> list[Paper]:
        """Search specified sources concurrently, deduplicate, and return unified results."""
        if sources is None:
            sources = list(self._sources.keys())

        active = {name: self._sources[name] for name in sources if name in self._sources}
        if not active:
            logger.warning("No valid sources specified: %s", sources)
            return []

        # Concurrent search
        tasks = [
            source.search(query, limit=limit_per_source, year_from=year_from, year_to=year_to)
            for source in active.values()
        ]
        results_per_source = await asyncio.gather(*tasks, return_exceptions=True)

        all_results: list[SearchResult] = []
        for name, result in zip(active.keys(), results_per_source, strict=True):
            if isinstance(result, Exception):
                logger.warning("Search failed for %s: %s", name, result)
            else:
                all_results.extend(result)  # type: ignore[arg-type]

        if deduplicate:
            return self._deduplicate(all_results)
        return [r.paper for r in all_results]

    async def get_citations(self, paper: Paper, limit: int = 50) -> list[Paper]:
        """Get citations from the paper's source."""
        source = self._sources.get(paper.source)
        if not source:
            return []
        return await source.get_citations(paper.id, limit=limit)

    async def get_references(self, paper: Paper, limit: int = 50) -> list[Paper]:
        """Get references from the paper's source."""
        source = self._sources.get(paper.source)
        if not source:
            return []
        return await source.get_references(paper.id, limit=limit)

    @staticmethod
    def _deduplicate(results: list[SearchResult]) -> list[Paper]:
        """Deduplicate papers by DOI or title hash, preferring Semantic Scholar data."""
        seen: list[Paper] = []  # type: ignore[assignment]
        dedup_keys: set[str] = set()

        # Sort to prefer semantic_scholar data when merging
        source_priority = {"semantic_scholar": 0, "arxiv": 1, "openalex": 2}
        sorted_results = sorted(
            results,
            key=lambda r: source_priority.get(r.source, 99),
        )

        for result in sorted_results:
            paper = result.paper
            key = paper.doi if paper.doi else _title_hash(paper.title)
            if key in dedup_keys:
                continue
            dedup_keys.add(key)
            seen.append(paper)  # type: ignore[arg-type]

        return seen  # type: ignore[return-value]

    @staticmethod
    def _default_sources() -> list[AcademicSearchSource]:
        """Create default sources from settings."""
        from backend.pipeline.literature.arxiv_source import ArxivSource
        from backend.pipeline.literature.openalex_source import OpenAlexSource
        from backend.pipeline.literature.semantic_scholar import SemanticScholarSource

        settings = get_settings()
        return [
            SemanticScholarSource(api_key=settings.semantic_scholar_api_key),
            ArxivSource(),
            OpenAlexSource(email=settings.openalex_email),
        ]


def _title_hash(title: str) -> str:
    normalized = title.lower().strip().replace(" ", "")
    return hashlib.md5(normalized.encode()).hexdigest()

"""Pipeline stages — composable units following the ActivationPipeline pattern."""

from __future__ import annotations

import asyncio
import json
import logging
from abc import ABC, abstractmethod
from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any, Generator

from backend.pipeline.ingestion.chunker import DocumentChunk  # noqa: F401 — re-exported by stages
from backend.pipeline.synthesis.proposal_synthesizer import ResearchProposal  # noqa: F401 — used by ProposalSynthesisStage

if TYPE_CHECKING:
    from backend.providers.base import LLMProvider
    from backend.pipeline.result import PipelineResult

logger = logging.getLogger(__name__)


@contextmanager
def _override_provider(
    service: object, override: LLMProvider | None
) -> Generator[None, None, None]:
    """Temporarily swap a service's _provider with the override."""
    if not override or not hasattr(service, "_provider"):
        yield
        return
    saved = service._provider  # type: ignore[attr-defined]
    try:
        service._provider = override  # type: ignore[attr-defined]
        yield
    finally:
        service._provider = saved  # type: ignore[attr-defined]


@dataclass
class StageContext:
    """Shared mutable state passed between stages."""

    result: PipelineResult
    all_papers: list = field(default_factory=list)
    db_run_id: int | None = None
    params: dict = field(default_factory=dict)
    domain: str = "AI/NLP"
    run_id: str = ""
    search_queries: list[str] | None = None
    max_gaps: int = 5
    rounds: int = 2
    ideas_per: int = 3
    export_format: str | None = "markdown"
    provider_override: Any = None  # LLMProvider override for model routing


class PipelineStage(ABC):
    """Base class for pipeline stages."""

    @property
    @abstractmethod
    def name(self) -> str:
        ...

    @abstractmethod
    async def execute(self, ctx: StageContext) -> bool:
        """Execute the stage. Return False to halt the pipeline."""
        ...


class LiteratureSearchStage(PipelineStage):
    def __init__(self, search, hooks):
        self._search = search
        self._hooks = hooks

    @property
    def name(self) -> str:
        return "literature_search"

    async def execute(self, ctx: StageContext) -> bool:
        queries = ctx.search_queries or [
            f"{ctx.domain} recent advances",
            f"{ctx.domain} open problems",
        ]
        all_papers = []
        for query in queries:
            papers = await self._search.search_all(query, limit_per_source=20)
            all_papers.extend(papers)
            logger.info("Found %d papers for query: %s", len(papers), query)

        # Deduplicate by paper ID (same paper can appear across multiple queries)
        seen = set()
        unique = []
        for p in all_papers:
            if p.id not in seen:
                seen.add(p.id)
                unique.append(p)
        ctx.all_papers = unique
        ctx.result.papers_found = len(unique)
        logger.info("Total unique papers: %d (from %d total)", len(unique), len(all_papers))

        if not all_papers:
            logger.warning("No papers found. Pipeline cannot continue.")
            return False
        return True


class IngestionStage(PipelineStage):
    def __init__(self, store, bm25, embedding, kg=None):
        self._store = store
        self._bm25 = bm25
        self._embedding = embedding
        self._kg = kg

    @property
    def name(self) -> str:
        return "ingestion"

    async def execute(self, ctx: StageContext) -> bool:
        # Deduplicate papers by ID — same paper can appear across multiple queries
        seen_ids = set()
        unique_papers = []
        for paper in ctx.all_papers:
            if paper.id not in seen_ids:
                seen_ids.add(paper.id)
                unique_papers.append(paper)
        ctx.all_papers = unique_papers
        logger.info("Ingestion: %d unique papers (from %d total)", len(unique_papers), len(ctx.all_papers))

        chunks = []
        for paper in ctx.all_papers:
            text = f"{paper.title}\n\n{paper.abstract or ''}"
            paper_chunks = [
                DocumentChunk(
                    text=text,
                    paper_id=paper.id,
                    section="abstract",
                    chunk_index=0,
                )
            ]
            chunks.append(paper_chunks)

        added = await self._store.add_papers(ctx.all_papers, chunks)
        logger.info("Added %d chunks to knowledge base", added)

        all_ids, all_texts, all_metas = [], [], []
        for paper, paper_chunks in zip(ctx.all_papers, chunks, strict=True):
            for j, chunk in enumerate(paper_chunks):
                all_ids.append(f"{paper.id}_chunk_{j}")
                all_texts.append(chunk.text)
                all_metas.append(
                    {
                        "paper_id": paper.id,
                        "paper_title": paper.title[:500],
                        "source": paper.source,
                    }
                )
        if all_ids:
            self._bm25.add_documents(all_ids, all_texts, all_metas)
            logger.info("Synced %d documents to BM25 index", len(all_ids))

        # Write to Knowledge Graph
        if self._kg:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.truth import TruthValue

            for paper in ctx.all_papers:
                entity = KnowledgeEntity(
                    id=f"paper:{paper.id}",
                    entity_type=EntityType.PAPER,
                    name=paper.title,
                    properties={
                        "source": paper.source,
                        "year": paper.year,
                        "citation_count": paper.citation_count,
                    },
                    truth=TruthValue.from_observation(frequency=0.9),
                )
                self._kg.add_entity(entity)
            self._kg.save()
            logger.info("Added %d paper entities to Knowledge Graph", len(ctx.all_papers))

        return True


class GapAnalysisStage(PipelineStage):
    def __init__(self, gap_analyzer, goal_manager, hooks, memory, kg=None, faithfulness_checker=None):
        self._gap_analyzer = gap_analyzer
        self._goal_manager = goal_manager
        self._hooks = hooks
        self._memory = memory
        self._kg = kg
        self._faithfulness_checker = faithfulness_checker

    @property
    def name(self) -> str:
        return "gap_analysis"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._gap_analyzer, ctx.provider_override):
            return await self._execute_gap_analysis(ctx)

    async def _execute_gap_analysis(self, ctx: StageContext) -> bool:
        prior_gaps = await self._recall_prior_gaps(ctx.domain)
        gaps, cluster_report = await self._gap_analyzer.analyze(
            ctx.all_papers,
            domain=ctx.domain,
            max_gaps=ctx.max_gaps,
            prior_gaps=prior_gaps,
        )
        ctx.result.gaps = gaps
        ctx.result.cluster_report = cluster_report
        logger.info("Identified %d research gaps", len(gaps))

        # Write gaps to Knowledge Graph
        if self._kg:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
            from backend.pipeline.knowledge.truth import TruthValue

            for gap in gaps:
                gap_entity = KnowledgeEntity(
                    id=f"gap:{gap.title[:60]}",
                    entity_type=EntityType.CONCEPT,
                    name=gap.title,
                    properties={
                        "gap_type": gap.gap_type,
                        "description": gap.description[:200],
                        "potential_impact": gap.potential_impact,
                    },
                    truth=TruthValue(frequency=gap.confidence, confidence=0.6),
                )
                self._kg.add_entity(gap_entity)
            self._kg.save()
            logger.info("Added %d gap entities to Knowledge Graph", len(gaps))

        # Faithfulness check: verify gap claims against source papers
        if self._faithfulness_checker and gaps:
            try:
                reports = await self._faithfulness_checker.check_gap_claims(
                    gaps, ctx.all_papers,
                )
                unfaithful = [r for r in reports if not r.is_faithful]
                if unfaithful:
                    logger.warning(
                        "Faithfulness check: %d/%d gaps have unfaithful claims",
                        len(unfaithful), len(gaps),
                    )
                    for r in unfaithful:
                        logger.warning("  Unfaithful: %s — %s", r.claim[:60], r.explanation[:100])
            except Exception as e:
                logger.warning("Faithfulness check failed: %s", e)

        if self._goal_manager and gaps:
            new_goals = self._goal_manager.create_from_gaps(gaps)
            logger.info("Created %d research goals from gaps", len(new_goals))

        for gap in gaps:
            await self._hooks.dispatch_sync_safe(
                "gap.found",
                {
                    "title": gap.title,
                    "confidence": gap.confidence,
                    "gap_type": gap.gap_type,
                },
            )
        return True

    async def _recall_prior_gaps(self, domain):
        if not self._memory:
            return None
        from backend.pipeline.memory.models import MemoryQuery, MemoryType

        results = await self._memory.recall(
            MemoryQuery(
                query=f"{domain} research gaps",
                memory_type=MemoryType.SEMANTIC,
                namespace="research_facts",
                top_k=20,
            )
        )
        return results if results else None


class IdeaGenerationStage(PipelineStage):
    def __init__(self, agent, hooks, dag_executor=None, dag_agents=None, provider=None, kg=None, forest=None, reasoning_verifier=None):
        self._agent = agent
        self._hooks = hooks
        self._dag_executor = dag_executor
        self._dag_agents = dag_agents
        self._provider = provider
        self._kg = kg
        self._forest = forest
        self._reasoning_verifier = reasoning_verifier

    @property
    def name(self) -> str:
        return "idea_generation"

    async def execute(self, ctx: StageContext) -> bool:
        provider = ctx.provider_override or self._provider
        with _override_provider(self._agent, provider):
            if self._dag_executor is not None:
                return await self._execute_dag(ctx, provider)
            return await self._execute_sequential(ctx)

    async def _execute_sequential(self, ctx: StageContext) -> bool:
        logger.info("Idea Generation (%d rounds, %d ideas/round)", ctx.rounds, ctx.ideas_per)
        ideas = await self._agent.run(
            gaps=ctx.result.gaps,
            context_papers=ctx.all_papers[:30],
            rounds=ctx.rounds,
            ideas_per_round=ctx.ideas_per,
        )
        ctx.result.ideas = ideas
        ctx.result.critique_history = self._agent.last_critique_history
        ctx.result.refinement_history = self._agent.last_refinement_history
        logger.info("Generated %d research ideas", len(ideas))

        # Write ideas to Knowledge Graph
        if self._kg and ideas:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
            from backend.pipeline.knowledge.truth import TruthValue

            for idea in ideas:
                idea_entity = KnowledgeEntity(
                    id=f"idea:{idea.title[:60]}",
                    entity_type=EntityType.CONCEPT,
                    name=idea.title,
                    properties={
                        "proposed_method": idea.proposed_method[:200],
                        "domain": idea.domain,
                    },
                    truth=TruthValue(frequency=idea.score, confidence=0.5),
                )
                self._kg.add_entity(idea_entity)

                for gap_id in idea.source_gap_ids:
                    gap_eid = f"gap:{gap_id[:60]}"
                    if gap_eid in self._kg._entities:
                        self._kg.add_relationship(KnowledgeRelationship(
                            source_id=gap_eid,
                            target_id=f"idea:{idea.title[:60]}",
                            relation_type=RelationType.PROPOSES_METHOD,
                            truth=TruthValue.from_observation(frequency=idea.score),
                        ))

            self._kg.save()
            logger.info("Added %d idea entities to Knowledge Graph", len(ideas))

        # Reasoning verification on top ideas
        if self._reasoning_verifier and ideas and ctx.result.gaps:
            try:
                for idea in ideas[:5]:
                    gap = ctx.result.gaps[0] if ctx.result.gaps else None
                    if gap:
                        result = await self._reasoning_verifier.verify_idea_reasoning(idea, gap)
                        if not result.passed:
                            logger.warning(
                                "Idea '%s' failed reasoning verification: %s",
                                idea.title[:60], "; ".join(result.issues[:3]),
                            )
            except Exception as e:
                logger.warning("Reasoning verification failed: %s", e)

        for idea in ideas:
            await self._hooks.dispatch_sync_safe(
                "idea.generated",
                {
                    "title": idea.title,
                    "score": idea.score,
                },
            )
        return True

    async def _execute_dag(self, ctx: StageContext, provider=None) -> bool:
        """Execute idea generation via the DAG executor."""
        from backend.pipeline.generation.agent_handlers import register_all_agents
        from backend.pipeline.generation.context_isolator import ContextIsolator
        from backend.pipeline.generation.models import ResearchIdea

        logger.info("Idea Generation via DAG (%d gaps)", len(ctx.result.gaps))

        isolator = ContextIsolator(ctx.result.gaps, ctx.all_papers[:30])

        # Register handlers for this run
        cleanup = register_all_agents(
            registry=self._dag_executor._registry,
            agents=self._dag_agents,
            isolator=isolator,
            provider=provider or self._provider,
        )

        # Prepare input: one item per gap
        dag_input = [
            {"gap": gap, "papers": ctx.all_papers[:30], "n_ideas": ctx.ideas_per}
            for gap in ctx.result.gaps
        ]

        try:
            results = await self._dag_executor.execute(dag_input)
        finally:
            # Restore buffered taxonomies
            for _, buffered, restore in cleanup:
                restore()

        # Extract ResearchIdea objects from results
        ideas = [i for i in results if isinstance(i, ResearchIdea)]
        if not ideas:
            # Try extracting from dicts
            for r in results:
                if isinstance(r, dict) and "ideas" in r:
                    ideas.extend(r["ideas"])

        ctx.result.ideas = ideas
        logger.info("DAG generated %d research ideas", len(ideas))

        for idea in ideas:
            await self._hooks.dispatch_sync_safe(
                "idea.generated",
                {"title": idea.title, "score": idea.score},
            )
        return True


class NoveltyCheckingStage(PipelineStage):
    def __init__(self, novelty_checker, hooks=None):
        self._novelty = novelty_checker
        self._hooks = hooks

    @property
    def name(self) -> str:
        return "novelty_checking"

    async def execute(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True
        for i, idea in enumerate(ideas):
            report = await self._novelty.check_novelty(idea)
            ctx.result.novelty_reports[i] = report
            logger.info("Novelty score for '%s': %.2f", idea.title[:50], report.overall_score)

        if self._hooks:
            for i, idea in enumerate(ideas):
                nr = ctx.result.novelty_reports.get(i)
                if nr:
                    await self._hooks.dispatch_sync_safe(
                        "idea.scored",
                        {
                            "title": idea.title,
                            "novelty_score": nr.overall_score,
                        },
                    )
        return True


class FeasibilityScoringStage(PipelineStage):
    def __init__(self, feasibility_scorer):
        self._feasibility = feasibility_scorer

    @property
    def name(self) -> str:
        return "feasibility_scoring"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._feasibility, ctx.provider_override):
            return await self._execute_feasibility(ctx)

    async def _execute_feasibility(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True
        from backend.config import get_settings
        settings = get_settings()
        for i, idea in enumerate(ideas):
            novelty = ctx.result.novelty_reports.get(i)
            report = await self._feasibility.score_feasibility(idea, novelty)
            # Counterfactual analysis (Gap 14)
            if settings.counterfactual_enabled:
                report = await self._feasibility.run_counterfactual(report)
            ctx.result.feasibility_reports[i] = report
            logger.info(
                "Feasibility score for '%s': %.1f/10", idea.title[:50], report.overall_score
            )
        return True


class ProposalSynthesisStage(PipelineStage):
    def __init__(
        self, synthesizer, governance_validator=None, governance_audit=None, ref_validator=None
    ):
        self._synthesizer = synthesizer
        self._governance_validator = governance_validator
        self._governance_audit = governance_audit
        self._ref_validator = ref_validator

    @property
    def name(self) -> str:
        return "proposal_synthesis"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._synthesizer, ctx.provider_override):
            return await self._execute_synthesis(ctx)

    async def _execute_synthesis(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True

        # Per-proposal timeout from settings (capped at 300s by HB-01)
        from backend.config import get_settings

        timeout = min(
            getattr(get_settings(), "per_proposal_timeout", 120.0),
            300.0,
        )

        for i, idea in enumerate(ideas):
            novelty = ctx.result.novelty_reports.get(i)
            feasibility = ctx.result.feasibility_reports.get(i)
            try:
                proposal = await asyncio.wait_for(
                    self._synthesizer.synthesize(
                        idea=idea,
                        novelty_report=novelty,
                        feasibility_report=feasibility,
                        supporting_papers=ctx.all_papers[:10],
                        gaps=ctx.result.gaps,
                    ),
                    timeout=timeout,
                )
            except asyncio.TimeoutError:
                logger.warning(
                    "Proposal synthesis timed out after %.1fs for idea %d: %s",
                    timeout, i + 1, idea.title[:50],
                )
                proposal = ResearchProposal(
                    title=idea.title,
                    abstract=f"Synthesis timed out after {timeout:.0f}s",
                    introduction="Timed out",
                    proposed_method=idea.proposed_method,
                )

            if self._governance_validator:
                proposal_md = proposal.to_markdown()
                validated_text, checks = await self._governance_validator.validate_with_reask(
                    proposal_md,
                    output_type="proposal",
                )
                proposal.sections["validated_text"] = validated_text

                if self._governance_audit:
                    from backend.pipeline.governance.events import (
                        GovernanceAuditLog,
                        GovernanceEvent,
                    )

                    verdict = (
                        "accepted"
                        if all(c.verdict.value != "rejected" for c in checks)
                        else "revised"
                    )
                    self._governance_audit.record(
                        GovernanceEvent(
                            event_type=f"output.{verdict}",
                            stage="proposal_synthesis",
                            content_hash=GovernanceAuditLog.content_hash(proposal_md),
                            checks_summary=f"{len(checks)} checks, verdict={verdict}",
                        )
                    )

            ctx.result.proposals[i] = proposal
            logger.info("Generated proposal for idea %d: %s", i + 1, idea.title[:50])

            # Reference validation
            if self._ref_validator:
                refs = proposal.sections.get("references", [])
                if isinstance(refs, list) and refs:
                    validation_results = await self._ref_validator.validate(refs)
                    proposal.sections["reference_validation"] = [
                        {"index": v.reference_index, "title": v.title, "status": v.status}
                        for v in validation_results
                    ]
                    unverified = sum(1 for v in validation_results if v.status == "unverified")
                    if unverified:
                        logger.info(
                            "Proposal %d: %d/%d references unverified",
                            i + 1,
                            unverified,
                            len(refs),
                        )
        return True


class TreeSearchStage(PipelineStage):
    """Pipeline stage that uses TreeSearchEngine for beam-search idea generation.

    Replaces IdeaGenerationStage when tree_of_thought_enabled=True (HB-01).
    The stage name is "idea_generation" so it occupies the same slot in
    STAGE_ORDER — all downstream persistence/checkpoint logic works unchanged.
    """

    # HB-03: Maximum serialized tree_data size in bytes (500KB)
    MAX_TREE_DATA_BYTES = 500 * 1024

    def __init__(
        self,
        engine: "TreeSearchEngine",
        hooks,
        provider=None,
        kg=None,
    ) -> None:
        self._engine = engine
        self._hooks = hooks
        self._provider = provider
        self._kg = kg

    @property
    def name(self) -> str:
        return "idea_generation"

    async def execute(self, ctx: StageContext) -> bool:
        logger.info(
            "TreeSearchStage: beam search (depth=%d, beam_width=%d)",
            self._engine.config.max_depth,
            self._engine.config.beam_width,
        )

        # Run beam search
        ideas = await self._engine.search(
            gaps=ctx.result.gaps,
            context_papers=ctx.all_papers[:30],
        )
        ctx.result.ideas = ideas
        logger.info("TreeSearchStage: generated %d ideas via tree search", len(ideas))

        # Serialize tree structure into tree_data for frontend (AC-01-03)
        tree_data = self._build_tree_data(ideas)
        ctx.result.tree_data = self._enforce_size_limit(tree_data)  # HB-03

        # Write ideas to Knowledge Graph (same as IdeaGenerationStage)
        if self._kg and ideas:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
            from backend.pipeline.knowledge.truth import TruthValue

            for idea in ideas:
                idea_entity = KnowledgeEntity(
                    id=f"idea:{idea.title[:60]}",
                    entity_type=EntityType.CONCEPT,
                    name=idea.title,
                    properties={
                        "proposed_method": idea.proposed_method[:200],
                    },
                    truth=TruthValue(frequency=getattr(idea, 'overall_score', 0.5), confidence=0.5),
                )
                self._kg.add_entity(idea_entity)

                for gap_id in getattr(idea, 'source_gap_ids', []):
                    gap_eid = f"gap:{gap_id[:60]}"
                    if gap_eid in self._kg._entities:
                        self._kg.add_relationship(KnowledgeRelationship(
                            source_id=gap_eid,
                            target_id=f"idea:{idea.title[:60]}",
                            relation_type=RelationType.PROPOSES_METHOD,
                            truth=TruthValue.from_observation(frequency=getattr(idea, 'overall_score', 0.5)),
                        ))

            self._kg.save()
            logger.info("Added %d idea entities to Knowledge Graph (tree search)", len(ideas))

        # Dispatch hooks
        for idea in ideas:
            await self._hooks.dispatch_sync_safe(
                "idea.generated",
                {
                    "title": idea.title,
                    "score": getattr(idea, 'overall_score', 0.0),
                },
            )
        return True

    def _build_tree_data(self, ideas: list) -> dict:
        """Build a serializable tree structure from generated ideas.

        The tree is reconstructed from the ideas' parent_idea_ids lineage
        fields, producing a flat node list with parent references that the
        frontend can render as an SVG tree.
        """
        nodes: list[dict] = []
        for idea in ideas:
            nodes.append({
                "id": idea.id,
                "title": idea.title,
                "score": getattr(idea, 'overall_score', 0.0),
                "proposed_method": idea.proposed_method[:200],
                "parent_ids": idea.parent_idea_ids or [],
            })

        return {
            "engine": "tree_search",
            "config": {
                "beam_width": self._engine.config.beam_width,
                "max_depth": self._engine.config.max_depth,
                "ideas_per_node": self._engine.config.ideas_per_node,
            },
            "nodes": nodes,
        }

    @classmethod
    def _enforce_size_limit(cls, tree_data: dict) -> dict | None:
        """Enforce 500KB limit on tree_data (HB-03).

        If serialized JSON exceeds the limit, truncate nodes to fit.
        Returns None if even an empty tree would exceed the limit (shouldn't happen).
        """
        serialized = json.dumps(tree_data, default=str)
        if len(serialized.encode("utf-8")) <= cls.MAX_TREE_DATA_BYTES:
            return tree_data

        # Try progressive truncation of nodes list
        nodes = tree_data.get("nodes", [])
        if isinstance(nodes, list):
            for trim_size in [len(nodes) // 2, len(nodes) // 4, 0]:
                tree_data_copy = dict(tree_data)
                tree_data_copy["nodes"] = nodes[:trim_size]
                serialized = json.dumps(tree_data_copy, default=str)
                if len(serialized.encode("utf-8")) <= cls.MAX_TREE_DATA_BYTES:
                    logger.warning(
                        "TreeSearchStage: tree_data truncated to %d nodes (HB-03: 500KB limit)",
                        trim_size,
                    )
                    return tree_data_copy

        logger.error("TreeSearchStage: tree_data exceeds 500KB even when empty — returning None")
        return None


class MechanicalMetricsStage(PipelineStage):
    """Compute objective mechanical metrics for each idea (BATCH-64).

    Runs after feasibility scoring so that all prior data (ideas, papers,
    gaps, novelty/feasibility reports) is available.  Metrics are stored
    on ``ctx.result.mechanical_metrics`` and merged into the novelty_report
    JSON during persistence — no schema change required.
    """

    def __init__(self):
        self._calculator = None

    @property
    def name(self) -> str:
        return "mechanical_metrics"

    async def execute(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True

        from backend.pipeline.evaluation.mechanical_metrics import MechanicalMetricsCalculator

        if self._calculator is None:
            self._calculator = MechanicalMetricsCalculator()

        for i, idea in enumerate(ideas):
            try:
                # Build supporting_papers for this idea
                cited_ids = set(getattr(idea, "supporting_papers", []) or [])
                supporting = [p for p in ctx.all_papers if getattr(p, "id", None) in cited_ids]

                metrics = self._calculator.compute_all(
                    idea=idea,
                    gaps=ctx.result.gaps,
                    supporting_papers=supporting,
                    all_domain_papers=ctx.all_papers,
                )
                ctx.result.mechanical_metrics[i] = metrics

                # Compute and log composite score (informational)
                novelty = ctx.result.novelty_reports.get(i)
                feasibility = ctx.result.feasibility_reports.get(i)
                llm_score = getattr(idea, "score", 0.0)
                nov_score = novelty.overall_score if novelty else 0.0
                feas_score = (feasibility.overall_score / 10.0) if feasibility else 0.0
                mech_avg = sum(metrics.values()) / len(metrics) if metrics else 0.0
                composite = 0.4 * llm_score + 0.3 * mech_avg + 0.3 * (nov_score + feas_score) / 2
                logger.info(
                    "Mechanical metrics for '%s': composite=%.3f, metrics=%s",
                    idea.title[:50], composite, metrics,
                )
            except Exception as e:
                logger.warning(
                    "Failed to compute mechanical metrics for idea %d: %s", i, e,
                )
        return True


class ExportStage(PipelineStage):
    def __init__(self, export_service):
        self._export = export_service

    @property
    def name(self) -> str:
        return "export"

    async def execute(self, ctx: StageContext) -> bool:
        if ctx.export_format and ctx.result.proposals:
            for i, proposal in ctx.result.proposals.items():
                path = await self._export.export(proposal, format=ctx.export_format)
                ctx.result.export_paths[i] = path
                logger.info("Exported proposal to: %s", path)
        return True

